CREATE OR REPLACE FUNCTION public.has_crm_access() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('admin','atendente')); $$;
REVOKE ALL ON FUNCTION public.has_crm_access() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_crm_access() TO authenticated, service_role;
DROP POLICY IF EXISTS "Authenticated can view leads" ON public.leads;
DROP POLICY IF EXISTS "Authenticated can update leads" ON public.leads;
DROP POLICY IF EXISTS "Authenticated can delete leads" ON public.leads;
DROP POLICY IF EXISTS "Anyone can insert leads" ON public.leads;
CREATE POLICY "CRM team read leads" ON public.leads FOR SELECT TO authenticated USING (public.has_crm_access());
CREATE POLICY "CRM team update leads" ON public.leads FOR UPDATE TO authenticated USING (public.has_crm_access()) WITH CHECK (public.has_crm_access());
CREATE POLICY "Admins delete leads" ON public.leads FOR DELETE TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY "CRM team insert leads" ON public.leads FOR INSERT TO authenticated WITH CHECK (public.has_crm_access());
CREATE POLICY "Validated website submissions" ON public.leads FOR INSERT TO anon, authenticated WITH CHECK (status='novo' AND origem='site' AND notes IS NULL AND char_length(btrim(coalesce(name,''))) BETWEEN 2 AND 200 AND whatsapp ~ '^[0-9()+ .-]{10,25}$' AND char_length(btrim(city)) BETWEEN 2 AND 200 AND char_length(coalesce(message,'')) <= 10000 AND char_length(coalesce(email,'')) <= 254 AND meta_lead_id IS NULL AND meta_campaign_id IS NULL AND campaign_name IS NULL AND category IS NULL AND whatsapp_received_at IS NULL AND sincronizado_meta=false AND ultimo_retorno_meta IS NULL AND ultimo_erro_meta IS NULL AND tag_origem_manual=false AND tag_origem_alterada_por IS NULL AND created_at BETWEEN now()-interval '5 minutes' AND now()+interval '1 minute');
GRANT SELECT, INSERT, UPDATE, DELETE ON public.leads TO authenticated;
GRANT INSERT ON public.leads TO anon;
REVOKE SELECT, UPDATE, DELETE ON public.leads FROM anon;
GRANT ALL ON public.leads TO service_role;
DROP POLICY IF EXISTS "Authenticated can insert lead status history" ON public.lead_status_history;
DROP POLICY IF EXISTS "Authenticated can view lead status history" ON public.lead_status_history;
CREATE POLICY "CRM team read status history" ON public.lead_status_history FOR SELECT TO authenticated USING (public.has_crm_access());
REVOKE INSERT, UPDATE, DELETE ON public.lead_status_history FROM anon, authenticated;
GRANT SELECT ON public.lead_status_history TO authenticated;
GRANT ALL ON public.lead_status_history TO service_role;
DROP POLICY IF EXISTS "Authenticated can insert origem history" ON public.lead_origem_history;
DROP POLICY IF EXISTS "Authenticated can view origem history" ON public.lead_origem_history;
CREATE POLICY "CRM team read origin history" ON public.lead_origem_history FOR SELECT TO authenticated USING (public.has_crm_access());
REVOKE INSERT, UPDATE, DELETE ON public.lead_origem_history FROM anon, authenticated;
GRANT SELECT ON public.lead_origem_history TO authenticated;
GRANT ALL ON public.lead_origem_history TO service_role;
DROP POLICY IF EXISTS "Authenticated can view meta logs" ON public.meta_integration_logs;
CREATE POLICY "Admins read Meta logs" ON public.meta_integration_logs FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "Authenticated can view assignments" ON public.user_profile_assignments;
CREATE POLICY "Own assignments or admin" ON public.user_profile_assignments FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "Authenticated can view company settings" ON public.company_settings;
CREATE POLICY "CRM team read company settings" ON public.company_settings FOR SELECT TO authenticated USING (public.has_crm_access());
DROP POLICY IF EXISTS "Read campaign rules" ON public.lead_campaign_rules;
CREATE POLICY "CRM team read campaign rules" ON public.lead_campaign_rules FOR SELECT TO authenticated USING (public.has_crm_access());
DROP POLICY IF EXISTS "Authenticated can view profile types" ON public.profile_types;
CREATE POLICY "CRM team read profile types" ON public.profile_types FOR SELECT TO authenticated USING (public.has_crm_access());
REVOKE ALL ON FUNCTION public.assign_lead_campaign(), public.classify_lead_tag_origem(), public.handle_new_user(), public.log_lead_tag_origem_change(), public.reapply_lead_campaign_rules() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.assign_lead_campaign(), public.classify_lead_tag_origem(), public.handle_new_user(), public.log_lead_tag_origem_change(), public.reapply_lead_campaign_rules() TO service_role;
REVOKE ALL ON FUNCTION public.create_public_lead(text,text,text,text,public.lead_status,public.lead_origem,text,text,text,text,text,text,text,text,text,text,text,text,text), public.create_public_lead(text,text,text,text,public.lead_status,public.lead_origem,text,text,text,text,text,text,text,text,text,text,text,text,text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.create_public_lead(text,text,text,text,public.lead_status,public.lead_origem,text,text,text,text,text,text,text,text,text,text,text,text,text), public.create_public_lead(text,text,text,text,public.lead_status,public.lead_origem,text,text,text,text,text,text,text,text,text,text,text,text,text,text) TO service_role;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated, service_role;